import secrets


class AccountService:
    def __init__(self) -> None:
        self._accounts: dict[str, dict] = {}
        self._tokens: dict[str, dict] = {}

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long")
        if email in self._accounts:
            raise ValueError("An account with this email already exists")
        self._accounts[email] = {
            "password": password,
            "is_admin": is_admin,
        }

    def login(self, email: str, password: str) -> bool:
        account = self._accounts.get(email)
        if account is None:
            return False
        return account["password"].lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester = self._accounts.get(requester_email)
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets")
        if target_email not in self._accounts:
            raise ValueError("No account with this email exists")
        token = secrets.token_urlsafe(32)
        self._tokens[token] = {"target_email": target_email, "used": False}
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long")
        record = self._tokens.get(token)
        if record is None:
            raise ValueError("Invalid reset token")
        if record["used"]:
            raise ValueError("Reset token has already been used")
        record["used"] = True
        target_email = record["target_email"]
        if target_email not in self._accounts:
            raise ValueError("Target account no longer exists")
        self._accounts[target_email]["password"] = new_password
